const labels={vocals:'Voz',bass:'Bajo',other:'Otros instrumentos',drums:'Batería',original:'Audio original',melody:'Melodía'};
export function packProject(p){return {format:'javita',version:1,...(p.origin==='hits'?{origin:'hits'}:{}),title:p.title,bpm:p.bpm,duration:p.duration,sourceStart:p.sourceStart||0,parts:p.parts.map(({key,notes})=>({key,notes:notes.map(({start,duration,pitch,amplitude})=>({start,duration,pitch,amplitude}))}))}}
export function unpackProject(x){if(!x||x.format!=='javita'||x.version!==1||typeof x.title!=='string'||!x.title.trim()||x.title.length>200||!Number.isFinite(x.bpm)||x.bpm<40||x.bpm>240||!Number.isFinite(x.duration)||x.duration<=0||x.duration>300||!Array.isArray(x.parts)||!x.parts.length||x.parts.length>8)throw Error('El archivo no es una transcripción JAVITA válida.');let count=0;const parts=x.parts.map((p,i)=>{if(!p||!labels[p.key]||!Array.isArray(p.notes))throw Error('Instrumento no válido.');count+=p.notes.length;if(count>30000)throw Error('El proyecto contiene demasiadas notas.');const notes=p.notes.map((n,j)=>{if(!n||![n.start,n.duration,n.pitch,n.amplitude].every(Number.isFinite)||n.start<0||n.start>=x.duration||n.duration<=0||n.start+n.duration>x.duration+.001||!Number.isInteger(n.pitch)||n.pitch<21||n.pitch>108||n.amplitude<0||n.amplitude>1)throw Error('Hay notas fuera de rango.');return {...n,id:j}});return {key:p.key,name:labels[p.key],notes,volume:.8,mute:false,solo:false,buffer:null,color:['#f6bd91','#b7a1ed','#9bd5cc','#e5a1b7'][i%4]}});return {...(x.origin==='hits'?{origin:'hits'}:{}),title:x.title,bpm:x.bpm,duration:x.duration,sourceStart:Number.isFinite(x.sourceStart)&&x.sourceStart>=0?x.sourceStart:0,parts,original:null}}
